def check_prime(num):
    # Step 1: Numbers <= 1 are not prime
    if num <= 1:
        return False

    # Step 2: Check divisors from 2 up to num - 1
    for i in range(2, num):
        if num % i == 0:
            return False  # Found a divisor, not prime

    return True  # No divisors found, it is prime

